'use client'

import { useEffect, useState } from 'react'
import { useRouter } from 'next/navigation'
import ModeratorShell, { useModeratorAuth } from './ModeratorShell'

type Stats = {
  activeFarmers: number
  consumers: number
  ordersThisWeek: number
  gmvThisWeek: number
  openEscalations: number
  pendingApprovals: number
}

export default function ModeratorDashboard() {
  const router = useRouter()
  const { zone, checked } = useModeratorAuth()
  const [stats, setStats] = useState<Stats | null>(null)
  const [error, setError] = useState('')

  useEffect(() => {
    if (!checked) return
    fetch('/api/moderator/stats', { credentials: 'same-origin' })
      .then((r) => r.json())
      .then((json) => {
        if (json?.stats) setStats(json.stats)
        else setError(json?.error ?? 'Could not load stats.')
      })
      .catch(() => setError('Network error.'))
  }, [checked])

  if (!checked || !zone) {
    return (
      <main className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="w-10 h-10 border-4 border-green-700 border-t-transparent rounded-full animate-spin" />
      </main>
    )
  }

  const today = new Date().toLocaleDateString('en-IN', {
    weekday: 'long', day: 'numeric', month: 'long', year: 'numeric',
  })

  const hasAlerts = (stats?.openEscalations ?? 0) > 0 || (stats?.pendingApprovals ?? 0) > 0

  return (
    <ModeratorShell title="Dashboard" subtitle={today} zone={zone}>
      {/* Alert strip */}
      {stats && (
        hasAlerts ? (
          <div className="bg-amber-50 border border-amber-200 text-amber-800 rounded-xl px-4 py-3 text-sm font-semibold mb-5">
            ⚠ {stats.pendingApprovals > 0 && `${stats.pendingApprovals} listing${stats.pendingApprovals > 1 ? 's' : ''} pending approval`}
            {stats.pendingApprovals > 0 && stats.openEscalations > 0 && ' · '}
            {stats.openEscalations > 0 && `${stats.openEscalations} open escalation${stats.openEscalations > 1 ? 's' : ''} need attention`}
          </div>
        ) : (
          <div className="bg-green-50 border border-green-200 text-green-800 rounded-xl px-4 py-3 text-sm font-semibold mb-5">
            ✓ All clear — no pending approvals or open escalations
          </div>

import { createHmac, timingSafeEqual } from 'crypto'
import Razorpay from 'razorpay'

// Server-only Razorpay helpers. The secret never leaves the server: it is
// used here to create orders and to verify the signature Checkout returns.
// The browser only ever sees the public key id (NEXT_PUBLIC_RAZORPAY_KEY_ID).

export function getRazorpayKeyId(): string {
  const id = process.env.NEXT_PUBLIC_RAZORPAY_KEY_ID
  if (!id) throw new Error('NEXT_PUBLIC_RAZORPAY_KEY_ID is not set.')
  return id
}

function getRazorpaySecret(): string {
  const secret = process.env.RAZORPAY_KEY_SECRET
  if (!secret) throw new Error('RAZORPAY_KEY_SECRET is not set.')
  return secret
}

export function getRazorpayClient(): Razorpay {
  return new Razorpay({ key_id: getRazorpayKeyId(), key_secret: getRazorpaySecret() })
}

export type RefundResult = {
  id: string
  status: string | null
  amountPaise: number
}

// Issue a (partial) refund against a captured payment. Each cart line is a
// separate orders row sharing one payment id, so we refund only this line's
// amount — Razorpay supports partial refunds, and the sum across declined
// lines can never exceed the captured total. Throws on API failure so the
// caller can keep the order in a state that lets the farmer retry.
export async function refundPayment(args: {
  paymentId: string
  amountPaise: number
  notes?: Record<string, string>
}): Promise<RefundResult> {
  const refund = await getRazorpayClient().payments.refund(args.paymentId, {
    amount: args.amountPaise,
    speed: 'normal',
    notes: args.notes,
  })
  return {
    id: String(refund.id),
    status: (refund.status as string | undefined) ?? null,
    amountPaise: Number(refund.amount) || args.amountPaise,
  }
}

// Recompute the Checkout signature and compare in constant time. Razorpay
// signs `${order_id}|${payment_id}` with HMAC-SHA256 keyed by the secret.
// A matching signature is the only proof the browser callback is genuine —
// never trust a client-reported "success" without this.
export function verifyPaymentSignature(args: {
  razorpayOrderId: string
  razorpayPaymentId: string
  signature: string
}): boolean {
  const expected = createHmac('sha256', getRazorpaySecret())
    .update(`${args.razorpayOrderId}|${args.razorpayPaymentId}`)
    .digest('hex')
  const a = Buffer.from(expected)
  const b = Buffer.from(args.signature)
  if (a.length !== b.length) return false
  return timingSafeEqual(a, b)
}

// Verify a Razorpay WEBHOOK signature. Webhooks are signed with the webhook
// secret (configured in the dashboard, separate from the API key secret):
// HMAC-SHA256 over the raw request body, hex-encoded. We must verify against
// the EXACT bytes received, so the route reads req.text() before parsing.
export function verifyWebhookSignature(rawBody: string, signature: string | null | undefined): boolean {
  const secret = process.env.RAZORPAY_WEBHOOK_SECRET
  if (!secret) throw new Error('RAZORPAY_WEBHOOK_SECRET is not set.')
  if (!signature) return false
  const expected = createHmac('sha256', secret).update(rawBody).digest('hex')
  const a = Buffer.from(expected)
  const b = Buffer.from(signature)
  if (a.length !== b.length) return false
  return timingSafeEqual(a, b)
}

// Fetch all payment attempts Razorpay recorded against one order. Used by
// reconciliation to decide whether a "pending" order was actually paid.
export async function fetchOrderPayments(orderId: string): Promise<Array<{ id: string; status: string }>> {
  const res = await getRazorpayClient().orders.fetchPayments(orderId)
  const items = (res as { items?: Array<{ id: string; status: string }> }).items ?? []
  return items.map((p) => ({ id: String(p.id), status: String(p.status) }))
}

// The shape we care about from a Razorpay payment entity (available both from
// payments.fetch and inside the payment.captured webhook payload).
export type RazorpayPaymentEntity = {
  method?: string | null
  vpa?: string | null
  wallet?: string | null
  bank?: string | null
  card?: { network?: string | null } | null
}

// Map a UPI VPA handle (the part after "@") to the app the buyer paid with.
// The handle is the most reliable signal Razorpay gives us — there is no
// explicit "app name" field for UPI.
function upiAppFromVpa(vpa?: string | null): string | null {
  if (!vpa || !vpa.includes('@')) return null
  const handle = vpa.split('@')[1]?.toLowerCase() ?? ''
  // PhonePe issues @ybl / @ibl / @axl (and @yapl for some banks).
  if (['ybl', 'ibl', 'axl', 'yapl'].includes(handle)) return 'PhonePe'
  // Google Pay handles all start with "ok" (okaxis, oksbi, okhdfcbank, okicici).
  if (handle.startsWith('ok')) return 'Google Pay'
  // Paytm.
  if (['paytm', 'ptyes', 'ptaxis', 'pthdfc', 'ptsbi'].includes(handle)) return 'Paytm'
  // Amazon Pay.
  if (handle === 'apl' || handle === 'amazonpay') return 'Amazon Pay'
  // CRED.
  if (handle === 'axisb' && (vpa.startsWith('cred') || vpa.includes('.cred'))) return 'CRED'
  return null
}

// Turn a Razorpay payment entity into a friendly label we can show buyers,
// e.g. "PhonePe", "Google Pay", "Paytm", "UPI", "Visa card", "HDFC NetBanking".
// Returns null when nothing useful can be derived.
export function resolvePaymentLabel(p: RazorpayPaymentEntity | null | undefined): string | null {
  if (!p) return null
  const method = (p.method ?? '').toLowerCase()
  if (method === 'upi') return upiAppFromVpa(p.vpa) ?? 'UPI'
  if (method === 'wallet') {
    const w = (p.wallet ?? '').toLowerCase()
    const map: Record<string, string> = {
      phonepe: 'PhonePe', paytm: 'Paytm', amazonpay: 'Amazon Pay',
      freecharge: 'Freecharge', mobikwik: 'MobiKwik', airtelmoney: 'Airtel Money',
    }
    return map[w] ?? (p.wallet ? `${p.wallet} wallet` : 'Wallet')
  }
  if (method === 'card') {
    const net = p.card?.network
    return net ? `${net} card` : 'Card'
  }
  if (method === 'netbanking') return p.bank ? `${p.bank} NetBanking` : 'NetBanking'
  if (method === 'emi') return 'EMI'
  if (method) return method.toUpperCase()
  return null
}

// Fetch a single payment from Razorpay and resolve its friendly method label.
// Used by the verify route; failures are swallowed (label stays null) so a
// transient API hiccup never blocks marking the order paid.
export async function fetchPaymentMethodLabel(paymentId: string): Promise<string | null> {
  try {
    const p = (await getRazorpayClient().payments.fetch(paymentId)) as RazorpayPaymentEntity
    return resolvePaymentLabel(p)
  } catch (e) {
    console.error('[YFF] fetchPaymentMethodLabel failed:', e)
    return null
  }
}

import { createClient } from '@supabase/supabase-js'
import { randomInt } from 'crypto'
import { NextRequest, NextResponse } from 'next/server'
import { getConsumerSessionFromRequest } from '@/lib/session'
import { createGuestOrderToken } from '@/lib/guest-order-token'
import { getTierPrice } from '@/lib/pricing'
import { normalizePhone } from '@/lib/phone'
import { DELIVERY_FEE_RUPEES } from '@/lib/delivery-fee'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

type IncomingItem = { listingId: string; qty: number }

// Pragmatic email check — we only need to reject obvious junk, not enforce
// RFC 5322. The real signal is whether the buyer can be reached.
const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/

// 4-digit handover code, generated server-side at order placement. The
// customer reads it off their order page to whoever hands over the goods —
// the rider (home delivery) or the farmer (self-pickup) — who confirms it in
// their dashboard. crypto.randomInt avoids Math.random's predictability.
function generateHandoverOtp(): string {
  return String(randomInt(0, 10000)).padStart(4, '0')
}

type ListingRow = {
  id: string
  name: string
  unit: string | null
  stock_qty: number | null
  farmer_id: string
  price_tier_1_qty: number | null
  price_tier_1_price: number | null
  price_tier_2_qty: number | null
  price_tier_2_price: number | null
  price_tier_3_price: number | null
}

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i

function bad(msg: string, status = 400) {
  return NextResponse.json({ error: msg }, { status })
}

export async function POST(req: NextRequest) {
  // No session is fine — guests may check out by providing name, email,
  // mobile, and address below (see the `guest` branch).
  const session = getConsumerSessionFromRequest(req)

  const body = await req.json().catch(() => null) as
    | {
        farmerId?: string
        paymentMethod?: string
        pickupLocation?: string | null
        items?: IncomingItem[]
        deliveryType?: string
        deliveryAddress?: string | null
        deliveryLandmark?: string | null
        deliveryPincode?: string | null
        deliveryAltPhone?: string | null
        idempotencyKey?: string | null
        guest?: { name?: string; email?: string; phone?: string } | null
      }
    | null

  if (!body) return bad('Invalid request body.')
  const { farmerId, paymentMethod, pickupLocation, items } = body
  // Optional idempotency key (a client-generated UUID per checkout attempt).
  const idempotencyKey = typeof body.idempotencyKey === 'string' && UUID_RE.test(body.idempotencyKey)
    ? body.idempotencyKey
    : null

  if (!farmerId || !UUID_RE.test(farmerId)) return bad('Invalid farmer.')
  if (paymentMethod !== 'upi' && paymentMethod !== 'cod' && paymentMethod !== 'razorpay') {
    return bad('Invalid payment method.')
  }
  if (!Array.isArray(items) || items.length === 0) return bad('Cart is empty.')
  if (items.length > 50) return bad('Too many items.')
  for (const it of items) {
    if (!it || typeof it !== 'object') return bad('Invalid item.')
    if (!it.listingId || !UUID_RE.test(it.listingId)) return bad('Invalid listing id.')
    if (!Number.isFinite(it.qty) || it.qty <= 0 || it.qty > 10000) return bad('Invalid quantity.')
  }

  // Guest checkout: no session, so the buyer's identity comes from the request.
  // We still never trust the client for prices or stock — only for who they are.
  const isGuest = !session
  let guestName: string | null = null
  let guestEmail: string | null = null
  let guestPhone: string | null = null
  if (isGuest) {
    guestName = String(body.guest?.name ?? '').trim().slice(0, 80)
    guestEmail = String(body.guest?.email ?? '').trim().toLowerCase().slice(0, 200)
    guestPhone = normalizePhone(body.guest?.phone)
    if (!guestName) return bad('Please enter your name.')
    if (!EMAIL_RE.test(guestEmail)) return bad('Enter a valid email address.')
    if (!guestPhone) return bad('Enter a valid 10-digit mobile number.')
  }

  // self_pickup → buyer collects from the farm; home_delivery → our rider
  // brings it; courier → the farmer ships it themselves. Both delivery kinds
  // need a destination address.
  const deliveryType =
    body.deliveryType === 'home_delivery' ? 'home_delivery'
    : body.deliveryType === 'courier' ? 'courier'
    : 'self_pickup'
  const needsAddress = deliveryType === 'home_delivery' || deliveryType === 'courier'
  let deliveryAddress: string | null = null
  let deliveryLandmark: string | null = null
  let deliveryPincode: string | null = null
  let deliveryAltPhone: string | null = null

  if (needsAddress) {
    deliveryAddress = String(body.deliveryAddress ?? '').trim().slice(0, 400)
    deliveryLandmark = String(body.deliveryLandmark ?? '').trim().slice(0, 200) || null
    const rawPincode = String(body.deliveryPincode ?? '').trim()
    deliveryPincode = /^\d{6}$/.test(rawPincode) ? rawPincode : null
    const altPhone = normalizePhone(body.deliveryAltPhone)
    deliveryAltPhone = altPhone || null

    if (!deliveryAddress) return bad('Enter your delivery address.')
    if (deliveryAddress.length < 10) return bad('Delivery address looks too short. Please add door no, street, and area.')
    if (!deliveryPincode) return bad('Enter a valid 6-digit pincode.')
  } else if (isGuest) {
    // Guests must always give an address, even for self-pickup, so the farmer
    // has a contact/record on file. We store it in delivery_address.
    deliveryAddress = String(body.deliveryAddress ?? '').trim().slice(0, 400)
    if (!deliveryAddress) return bad('Enter your address.')
    if (deliveryAddress.length < 10) return bad('Address looks too short. Please add door no, street, and area.')
  }

  const supabase = createClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.SUPABASE_SERVICE_ROLE_KEY!,
  )

  // Resolve the authoritative buyer. For accounts we read name/phone from the
  // DB (never the client); for guests we use the values validated above and
  // leave consumer_id NULL.
  let buyerId: string | null = null
  let buyerName: string
  let buyerPhone: string
  let buyerEmail: string | null = null
  if (session) {
    const { data: consumer } = await supabase
      .from('consumers_auth')
      .select('id, name, phone')
      .eq('id', session.consumerId)
      .maybeSingle()
    if (!consumer) return bad('Account not found. Please log in again.', 401)
    buyerId = consumer.id
    buyerName = consumer.name || 'Buyer'
    buyerPhone = consumer.phone
  } else {
    buyerName = guestName || 'Buyer'
    buyerPhone = guestPhone!
    buyerEmail = guestEmail
  }

  // Idempotency: if this checkout attempt was already saved (double-tap or a
  // retry after a lost response), return the existing rows instead of placing
  // a second order and decrementing stock again. Guest orders have no
  // consumer_id, so we match on the (random UUID) key alone for them.
  if (idempotencyKey) {
    let existingQuery = supabase
      .from('orders')
      .select('id, order_code, total_price, delivery_fee')
      .eq('idempotency_key', idempotencyKey)
    existingQuery = buyerId
      ? existingQuery.eq('consumer_id', buyerId)
      : existingQuery.is('consumer_id', null)
    const { data: existing } = await existingQuery
    if (existing && existing.length > 0) {
      const existingTotal = existing.reduce((s, o) => s + (Number(o.total_price) || 0), 0)
      const existingFee = existing.reduce((s, o) => s + (Number(o.delivery_fee) || 0), 0)
      const existingIds = existing.map((r) => r.id)
      return NextResponse.json({
        ok: true,
        orderIds: existingIds,
        orderCodes: existing.map((r) => (r as { order_code?: string | null }).order_code).filter(Boolean),
        total: existingTotal,
        deliveryFee: existingFee,
        grandTotal: existingTotal + existingFee,
        deduplicated: true,
        ...(isGuest ? { guestToken: createGuestOrderToken(existingIds) } : {}),
      })
    }
  }

  // Farmer COD acceptance check
  const { data: farmer } = await supabase
    .from('farmers')
    .select('id, cod_enabled')
    .eq('id', farmerId)
    .maybeSingle()

  if (!farmer) return bad('Farmer not found.', 404)
  if (paymentMethod === 'cod' && farmer.cod_enabled !== true) {
    return bad('This farmer is not accepting Cash on Delivery.')
  }

  // Pull live listing rows — never trust prices from the client cart
  const listingIds = items.map((i) => i.listingId)
  const { data: listings } = await supabase
    .from('produce_listings')
    .select(
      'id, name, unit, stock_qty, farmer_id, price_tier_1_qty, price_tier_1_price, price_tier_2_qty, price_tier_2_price, price_tier_3_price',
    )
    .in('id', listingIds) as { data: ListingRow[] | null }

  if (!listings || listings.length !== listingIds.length) {
    return bad('One or more items in your cart are no longer available.')
  }

  const listingById = new Map(listings.map((l) => [l.id, l]))
  const rows: Array<Record<string, unknown>> = []
  let total = 0
  // One OTP for the whole batch. Home delivery: the rider does a single
  // handover at the door. Self-pickup: the customer reads it to the farmer at
  // collection. Either way the whole checkout shares one code.
  const sharedHandoverOtp = generateHandoverOtp()
  const deliveryFee = deliveryType === 'home_delivery' ? DELIVERY_FEE_RUPEES : 0

  // Validate first (price + ownership) before we touch any stock. Stock
  // claims happen below with the RPC so two cart submits can't oversell.
  for (const item of items) {
    const listing = listingById.get(item.listingId)
    if (!listing) return bad('Item missing.')
    if (listing.farmer_id !== farmerId) return bad('Items must belong to the same farmer.')

    const unitPrice = getTierPrice(item.qty, {
      priceTier1Qty: listing.price_tier_1_qty,
      priceTier1Price: listing.price_tier_1_price,
      priceTier2Qty: listing.price_tier_2_qty,
      priceTier2Price: listing.price_tier_2_price,
      priceTier3Price: listing.price_tier_3_price,
    })

    const linePrice = unitPrice != null ? Math.round(unitPrice * item.qty) : null
    if (linePrice == null || linePrice <= 0) {
      return bad(`Price not set for ${listing.name}. Please ask the farmer.`)
    }
    total += linePrice

    rows.push({
      farmer_id: farmerId,
      produce_listing_id: listing.id,
      produce_name: listing.name,
      quantity: item.qty,
      unit: listing.unit || 'kg',
      total_price: linePrice,
      buyer_name: buyerName,
      buyer_phone: buyerPhone,
      buyer_email: buyerEmail,
      consumer_id: buyerId,
      idempotency_key: idempotencyKey,
      pickup_location: typeof pickupLocation === 'string' ? pickupLocation.slice(0, 200) : null,
      status: 'pending',
      payment_method: paymentMethod,
      payment_status: 'pending',
      delivery_type: deliveryType,
      delivery_status: deliveryType === 'home_delivery' ? 'unassigned' : null,
      delivery_address: deliveryAddress,
      delivery_landmark: deliveryLandmark,
      delivery_pincode: deliveryPincode,
      delivery_alt_phone: deliveryAltPhone,
      handover_otp: sharedHandoverOtp,
      // Fee is paid once per cart, so we stamp it on the first row only.
      // sum(delivery_fee) and sum(rider_payout) over a batch === one fee.
      delivery_fee: 0,
      rider_payout: 0,
    })
  }

  if (rows.length > 0 && deliveryFee > 0) {
    rows[0].delivery_fee = deliveryFee
    rows[0].rider_payout = deliveryFee
  }

  // Atomic stock claim. decrement_stock returns false if the listing went
  // below zero (or vanished). On any failure we revert prior claims so we
  // don't leak inventory.
  const claimed: Array<{ listingId: string; qty: number }> = []
  const revertClaims = async () => {
    for (const c of claimed) {
      try {
        await supabase.rpc('increment_stock', { p_listing_id: c.listingId, p_qty: c.qty })
      } catch (e) {
        console.error('[YFF] increment_stock revert failed:', e)
      }
    }
  }
  for (const item of items) {
    const listing = listingById.get(item.listingId)!
    const { data: ok, error: rpcErr } = await supabase.rpc('decrement_stock', {
      p_listing_id: item.listingId,
      p_qty: item.qty,
    })
    if (rpcErr) {
      console.error('[YFF] decrement_stock rpc failed:', rpcErr.message)
      await revertClaims()
      return bad('Could not place order. Please try again.', 500)
    }
    if (!ok) {
      await revertClaims()
      return bad(`${listing.name} just sold out. Please reduce the quantity and try again.`)
    }
    claimed.push({ listingId: item.listingId, qty: item.qty })
  }

  const { data: inserted, error: insertErr } = await supabase
    .from('orders')
    .insert(rows)
    .select('id, order_code')

  if (insertErr || !inserted) {
    console.error('[YFF] place-order insert failed:', insertErr?.message)
    // Roll the stock back so the row isn't lost.
    await revertClaims()
    return bad('Could not place order. Please try again.', 500)
  }

  const orderIds = inserted.map((r) => r.id)
  return NextResponse.json({
    ok: true,
    orderIds,
    orderCodes: inserted.map((r) => (r as { order_code?: string | null }).order_code).filter(Boolean),
    total,
    deliveryFee,
    grandTotal: total + deliveryFee,
    // Guests get a short-lived token bound to these orders so they can finish
    // the Razorpay create/verify pair without a session cookie.
    ...(isGuest ? { guestToken: createGuestOrderToken(orderIds) } : {}),
  })
}

import { createClient } from '@supabase/supabase-js'
import { NextRequest, NextResponse } from 'next/server'
import { getConsumerSessionFromRequest } from '@/lib/session'
import { verifyGuestOrderToken } from '@/lib/guest-order-token'
import { verifyPaymentSignature, fetchPaymentMethodLabel } from '@/lib/razorpay'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

// Step 4: Checkout returns three values to the browser, which posts them
// here. We re-verify the signature server-side and only then mark the orders
// paid. A forged callback fails the HMAC check and changes nothing.
export async function POST(req: NextRequest) {
  // Guests have no session — they authorize with the guestToken from
  // /api/orders/place (validated below against the rows we resolve).
  const session = getConsumerSessionFromRequest(req)

  const body = await req.json().catch(() => null) as
    | {
        razorpayOrderId?: string
        razorpayPaymentId?: string
        razorpaySignature?: string
        guestToken?: string
      }
    | null

  const razorpayOrderId = String(body?.razorpayOrderId ?? '')
  const razorpayPaymentId = String(body?.razorpayPaymentId ?? '')
  const razorpaySignature = String(body?.razorpaySignature ?? '')
  if (!razorpayOrderId || !razorpayPaymentId || !razorpaySignature) {
    return NextResponse.json({ error: 'Missing payment fields.' }, { status: 400 })
  }

  const valid = verifyPaymentSignature({ razorpayOrderId, razorpayPaymentId, signature: razorpaySignature })
  if (!valid) {
    console.warn('[YFF] razorpay signature verification FAILED for', razorpayOrderId)
    return NextResponse.json({ error: 'Payment could not be verified.' }, { status: 400 })
  }

  const supabase = createClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.SUPABASE_SERVICE_ROLE_KEY!,
  )

  // Find our rows by the Razorpay order id we stamped at create time, and
  // confirm they belong to this consumer before flipping them to paid.
  const { data: orders } = await supabase
    .from('orders')
    .select('id, consumer_id')
    .eq('razorpay_order_id', razorpayOrderId)

  if (!orders || orders.length === 0) {
    return NextResponse.json({ error: 'Order not found.' }, { status: 404 })
  }
  if (session) {
    if (orders.some((o) => o.consumer_id !== session.consumerId)) {
      return NextResponse.json({ error: 'Not your order.' }, { status: 403 })
    }
  } else {
    // Guest: rows must be guest orders, and the token must cover exactly them.
    if (orders.some((o) => o.consumer_id !== null)) {
      return NextResponse.json({ error: 'Not your order.' }, { status: 403 })
    }
    if (!verifyGuestOrderToken(body?.guestToken, orders.map((o) => o.id))) {
      return NextResponse.json({ error: 'Please log in.' }, { status: 401 })
    }
  }

  // Resolve the friendly payment method (PhonePe / Google Pay / UPI / Card…)
  // from the Razorpay payment so we can show it instead of "Razorpay". A
  // failure here just leaves the label null — it never blocks marking paid.
  const methodLabel = await fetchPaymentMethodLabel(razorpayPaymentId)

  const { error } = await supabase
    .from('orders')
    .update({
      payment_status: 'paid',
      paid_at: new Date().toISOString(),
      razorpay_payment_id: razorpayPaymentId,
      ...(methodLabel ? { payment_method_detail: methodLabel } : {}),
    })
    .eq('razorpay_order_id', razorpayOrderId)

  if (error) {
    console.error('[YFF] razorpay verify update failed:', error.message)
    return NextResponse.json({ error: 'Could not record payment. Please try again.' }, { status: 500 })
  }

  return NextResponse.json({ ok: true, orderIds: orders.map((o) => o.id) })
}

import { createClient } from '@supabase/supabase-js'
import { NextRequest, NextResponse } from 'next/server'
import { verifyWebhookSignature } from '@/lib/razorpay'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

// Razorpay → our server, independent of the buyer's browser. This is the
// authoritative payment confirmation: if the buyer's phone dies right after
// paying, the browser-side /verify never runs, but this webhook still marks
// the order paid. Configure it in the Razorpay dashboard:
//   Settings → Webhooks → add URL .../api/orders/razorpay/webhook
//   events: payment.captured, payment.failed  (+ a webhook secret)
// and set RAZORPAY_WEBHOOK_SECRET to that secret.
//
// We always answer 200 once the signature is valid so Razorpay stops
// retrying; processing failures are logged, not surfaced to Razorpay.
export async function POST(req: NextRequest) {
  // Read the RAW body first — signature is computed over these exact bytes.
  const raw = await req.text()
  const signature = req.headers.get('x-razorpay-signature')

  let valid: boolean
  try {
    valid = verifyWebhookSignature(raw, signature)
  } catch (e) {
    console.error('[YFF] webhook secret missing/misconfigured:', e)
    return NextResponse.json({ error: 'Webhook not configured.' }, { status: 500 })
  }
  if (!valid) {
    console.warn('[YFF] razorpay webhook signature INVALID')
    return NextResponse.json({ error: 'Invalid signature.' }, { status: 400 })
  }

  let event: {
    event?: string
    payload?: { payment?: { entity?: { id?: string; order_id?: string } } }
  }
  try {
    event = JSON.parse(raw)
  } catch {
    return NextResponse.json({ error: 'Bad JSON.' }, { status: 400 })
  }

  const supabase = createClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.SUPABASE_SERVICE_ROLE_KEY!,
  )

  const payment = event.payload?.payment?.entity
  const razorpayOrderId = payment?.order_id
  const razorpayPaymentId = payment?.id

  try {
    if (event.event === 'payment.captured' && razorpayOrderId) {
      // Mark paid only if not already — keeps the webhook idempotent against
      // Razorpay's retries and against a browser /verify that already ran.
      const { error } = await supabase
        .from('orders')
        .update({ payment_status: 'paid', razorpay_payment_id: razorpayPaymentId ?? null })
        .eq('razorpay_order_id', razorpayOrderId)
        .neq('payment_status', 'paid')
      if (error) console.error('[YFF] webhook captured update failed:', error.message)
    } else if (event.event === 'payment.failed' && razorpayOrderId) {
      const { error } = await supabase
        .from('orders')
        .update({ payment_status: 'failed' })
        .eq('razorpay_order_id', razorpayOrderId)
        .eq('payment_status', 'pending')
      if (error) console.error('[YFF] webhook failed update failed:', error.message)
    }
    // Unknown events are acknowledged and ignored.
  } catch (e) {
    console.error('[YFF] webhook processing error:', e)
  }

  return NextResponse.json({ ok: true })
}

import { createClient } from '@supabase/supabase-js'
import { NextRequest, NextResponse } from 'next/server'
import { getConsumerSessionFromRequest } from '@/lib/session'
import { verifyGuestOrderToken } from '@/lib/guest-order-token'
import { getRazorpayClient, getRazorpayKeyId } from '@/lib/razorpay'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i

// Step 2 of the Razorpay flow: the browser has already placed the orders
// (status pending) via /api/orders/place. Here we create the matching
// Razorpay order for the AUTHORITATIVE total read from the DB, never an
// amount sent by the client, and stamp its id onto our rows.
export async function POST(req: NextRequest) {
  // Guests have no session — they authorize with the short-lived guestToken
  // returned by /api/orders/place, bound to exactly these order ids.
  const session = getConsumerSessionFromRequest(req)

  const body = await req.json().catch(() => null)
  const rawIds = (body as { orderIds?: unknown } | null)?.orderIds
  const guestToken = (body as { guestToken?: unknown } | null)?.guestToken
  const orderIds = Array.isArray(rawIds) ? rawIds.map((x) => String(x)) : []
  if (orderIds.length === 0) return NextResponse.json({ error: 'Missing order ids.' }, { status: 400 })
  if (orderIds.length > 50) return NextResponse.json({ error: 'Too many orders.' }, { status: 400 })
  for (const id of orderIds) {
    if (!UUID_RE.test(id)) return NextResponse.json({ error: 'Invalid order id.' }, { status: 400 })
  }

  const supabase = createClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.SUPABASE_SERVICE_ROLE_KEY!,
  )

  const { data: orders } = await supabase
    .from('orders')
    .select('id, consumer_id, total_price, payment_status, razorpay_order_id')
    .in('id', orderIds)

  if (!orders || orders.length !== orderIds.length) {
    return NextResponse.json({ error: 'Order not found.' }, { status: 404 })
  }
  if (session) {
    if (orders.some((o) => o.consumer_id !== session.consumerId)) {
      return NextResponse.json({ error: 'Not your order.' }, { status: 403 })
    }
  } else {
    // Guest: every row must be a guest order, and the token must cover them.
    if (orders.some((o) => o.consumer_id !== null)) {
      return NextResponse.json({ error: 'Not your order.' }, { status: 403 })
    }
    if (typeof guestToken !== 'string' || !verifyGuestOrderToken(guestToken, orderIds)) {
      return NextResponse.json({ error: 'Please log in.' }, { status: 401 })
    }
  }
  // Don't let an already-paid batch be charged a second time.
  if (orders.some((o) => o.payment_status === 'paid')) {
    return NextResponse.json({ error: 'These orders are already paid.' }, { status: 409 })
  }

  // Authoritative amount: sum the product line totals stored at placement.
  // Delivery fee is intentionally excluded — it's collected as cash by the
  // rider, matching the existing UX. Razorpay works in paise.
  const totalRupees = orders.reduce((s, o) => s + (Number(o.total_price) || 0), 0)
  if (totalRupees <= 0) return NextResponse.json({ error: 'Invalid order total.' }, { status: 400 })
  const amountPaise = Math.round(totalRupees * 100)

  // Idempotency: if this batch already has a Razorpay order (the buyer retried
  // after a dropped connection), reuse it rather than creating a second order
  // the buyer could be charged for separately.
  const existingRzpId = orders[0].razorpay_order_id as string | null | undefined
  if (existingRzpId && orders.every((o) => o.razorpay_order_id === existingRzpId)) {
    return NextResponse.json({
      ok: true,
      keyId: getRazorpayKeyId(),
      razorpayOrderId: existingRzpId,
      amount: amountPaise,
      currency: 'INR',
      reused: true,
    })
  }

  let rzpOrder
  try {
    rzpOrder = await getRazorpayClient().orders.create({
      amount: amountPaise,
      currency: 'INR',
      // Razorpay caps receipt at 40 chars — use the first order id.
      receipt: orderIds[0],
      notes: { orderIds: orderIds.join(',') },
    })
  } catch (e) {
    console.error('[YFF] razorpay order create failed:', e)
    return NextResponse.json({ error: 'Could not start payment. Please try again.' }, { status: 502 })
  }

  const { error: updErr } = await supabase
    .from('orders')
    .update({ razorpay_order_id: rzpOrder.id })
    .in('id', orderIds)
  if (updErr) {
    console.error('[YFF] razorpay order id stamp failed:', updErr.message)
    return NextResponse.json({ error: 'Could not start payment. Please try again.' }, { status: 500 })
  }

  return NextResponse.json({
    ok: true,
    keyId: getRazorpayKeyId(),
    razorpayOrderId: rzpOrder.id,
    amount: amountPaise,
    currency: 'INR',
  })
}

import { createClient } from '@supabase/supabase-js'
import { NextRequest, NextResponse } from 'next/server'
import { getFarmerSessionFromRequest } from '@/lib/farmer-session'
import { refundPayment } from '@/lib/razorpay'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i

// Farmer declines a pending order. This runs server-side (not in the
// dashboard) because issuing a real refund needs the Razorpay secret. Steps:
//   1. authorise the farmer and confirm the order is theirs and still pending
//   2. return the reserved stock
//   3. if the buyer paid by Razorpay, issue a real partial refund for this
//      line's amount and record it; other paid methods get a manual
//      'initiated' marker as before
//   4. mark the order declined
export async function POST(req: NextRequest, ctx: { params: Promise<{ id: string }> }) {
  const session = getFarmerSessionFromRequest(req)
  if (!session) return NextResponse.json({ error: 'Please log in.' }, { status: 401 })

  const { id } = await ctx.params
  if (!id || !UUID_RE.test(id)) return NextResponse.json({ error: 'Invalid order id.' }, { status: 400 })

  const body = await req.json().catch(() => null)
  const reason = String((body as { reason?: unknown } | null)?.reason ?? '').trim().slice(0, 300)

  const supabase = createClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.SUPABASE_SERVICE_ROLE_KEY!,
  )

  const { data: order, error: loadErr } = await supabase
    .from('orders')
    .select('id, farmer_id, status, quantity, total_price, produce_listing_id, payment_method, payment_status, razorpay_payment_id, order_code')
    .eq('id', id)
    .maybeSingle()

  if (loadErr) return NextResponse.json({ error: loadErr.message }, { status: 500 })
  if (!order) return NextResponse.json({ error: 'Order not found.' }, { status: 404 })
  if (order.farmer_id !== session.farmerId) {
    return NextResponse.json({ error: 'Not your order.' }, { status: 403 })
  }
  // Only a pending order can be declined. This also makes the call idempotent:
  // a double-tap finds the order already declined and refunds nothing twice.
  if (order.status !== 'pending') {
    return NextResponse.json({ error: 'This order can no longer be declined.' }, { status: 409 })
  }

  // 1. Return the reserved stock.
  if (order.produce_listing_id && order.quantity != null && order.quantity > 0) {
    try {
      await supabase.rpc('increment_stock', {
        p_listing_id: order.produce_listing_id,
        p_qty: order.quantity,
      })
    } catch (e) {
      console.error('[YFF] restock on decline failed:', e)
    }
  }

  // 2. Refund if the buyer actually paid.
  const update: Record<string, unknown> = { status: 'declined', decline_reason: reason || null }

  const paidByRazorpay = order.payment_status === 'paid' && !!order.razorpay_payment_id
  const paidByOther =
    order.payment_status === 'completed' ||
    order.payment_status === 'payment_claimed' ||
    order.payment_status === 'pending_confirmation'

  if (paidByRazorpay) {
    const amountPaise = Math.round((Number(order.total_price) || 0) * 100)
    if (amountPaise > 0) {
      try {
        const refund = await refundPayment({
          paymentId: order.razorpay_payment_id as string,
          amountPaise,
          notes: { order_code: order.order_code ?? '', order_id: order.id },
        })
        update.refund_id = refund.id
        update.refund_status = refund.status ?? 'processed'
        update.refund_amount = Math.round(refund.amountPaise / 100)
        update.refunded_at = new Date().toISOString()
      } catch (e) {
        // Refund failed at Razorpay. Don't silently swallow it — keep the
        // order pending so the farmer can retry, and surface the error.
        console.error('[YFF] razorpay refund failed:', e)
        return NextResponse.json(
          { error: 'Could not issue the refund. The order was not declined — please try again.' },
          { status: 502 },
        )
      }
    }
  } else if (paidByOther) {
    // Non-Razorpay paid (UPI/manual): flag for manual refund as before.
    update.refund_status = 'initiated'
  }

  const { error: updErr } = await supabase.from('orders').update(update).eq('id', id)
  if (updErr) {
    console.error('[YFF] decline update failed:', updErr.message)
    return NextResponse.json({ error: 'Could not decline the order. Please try again.' }, { status: 500 })
  }

  return NextResponse.json({
    ok: true,
    refunded: !!update.refund_id,
    refundStatus: (update.refund_status as string | undefined) ?? null,
  })
}

// Tier-pricing helper, shared between the client cart and the server place-order
// endpoint so the totals stay in lockstep no matter which side computes them.

export type TierInputs = {
  pricePerKg?: number | null
  priceTier1Qty?: number | null
  priceTier1Price?: number | null
  priceTier2Qty?: number | null
  priceTier2Price?: number | null
  priceTier3Price?: number | null
}

export function getTierPrice(qty: number, item: TierInputs): number | null {
  const {
    pricePerKg,
    priceTier1Qty,
    priceTier1Price,
    priceTier2Qty,
    priceTier2Price,
    priceTier3Price,
  } = item

  if (priceTier1Qty == null || priceTier1Price == null) {
    return pricePerKg ?? null
  }
  if (qty <= priceTier1Qty) return priceTier1Price
  if (priceTier2Qty != null && priceTier2Price != null) {
    if (qty <= priceTier2Qty) return priceTier2Price
    return priceTier3Price ?? priceTier2Price
  }
  if (priceTier3Price != null) return priceTier3Price
  return priceTier1Price
}

// Tiny in-memory token-bucket-ish limiter. Per-process only — fine for a single
// Vercel region; for multi-region scale we'd swap to Redis. Enough to slow
// brute-force on /api/consumer/login until that's needed.

type Bucket = { count: number; windowStart: number }
const buckets = new Map<string, Bucket>()

const SWEEP_INTERVAL_MS = 60 * 60 * 1000 // 1h
let lastSweep = Date.now()

function sweep(now: number) {
  if (now - lastSweep < SWEEP_INTERVAL_MS) return
  lastSweep = now
  // Drop entries whose window has long expired (≥1h)
  for (const [k, b] of buckets) {
    if (now - b.windowStart > SWEEP_INTERVAL_MS) buckets.delete(k)
  }
}

/**
 * Returns true when the request is allowed (under the limit), false when blocked.
 * @param key identifier — combine ip + phone for login attempts
 * @param max max attempts per window
 * @param windowMs window length in ms
 */
export function rateLimit(key: string, max: number, windowMs: number): boolean {
  const now = Date.now()
  sweep(now)
  const bucket = buckets.get(key)
  if (!bucket || now - bucket.windowStart > windowMs) {
    buckets.set(key, { count: 1, windowStart: now })
    return true
  }
  if (bucket.count >= max) return false
  bucket.count += 1
  return true
}

import { createClient } from '@supabase/supabase-js'
import { NextRequest, NextResponse } from 'next/server'
import { getConsumerSessionFromRequest } from '@/lib/session'
import { refundPayment } from '@/lib/razorpay'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i
const CANCEL_WINDOW_MS = 30 * 60 * 1000 // 30 minutes

// Buyer cancels their own order. Allowed only while it is still pending (the
// farmer hasn't confirmed) AND within 30 minutes of placing it. Returns the
// stock and, for a paid order, issues a real Razorpay refund — same machinery
// as a farmer decline, but initiated by the buyer.
export async function POST(req: NextRequest, ctx: { params: Promise<{ id: string }> }) {
  const session = getConsumerSessionFromRequest(req)
  if (!session) return NextResponse.json({ error: 'Please log in.' }, { status: 401 })

  const { id } = await ctx.params
  if (!id || !UUID_RE.test(id)) return NextResponse.json({ error: 'Invalid order id.' }, { status: 400 })

  const supabase = createClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.SUPABASE_SERVICE_ROLE_KEY!,
  )

  const { data: order, error: loadErr } = await supabase
    .from('orders')
    .select('id, consumer_id, status, quantity, total_price, produce_listing_id, payment_status, razorpay_payment_id, created_at, order_code')
    .eq('id', id)
    .maybeSingle()

  if (loadErr) return NextResponse.json({ error: loadErr.message }, { status: 500 })
  if (!order) return NextResponse.json({ error: 'Order not found.' }, { status: 404 })
  if (order.consumer_id !== session.consumerId) {
    return NextResponse.json({ error: 'Not your order.' }, { status: 403 })
  }
  if (order.status !== 'pending') {
    return NextResponse.json(
      { error: 'This order can no longer be cancelled — the farmer has already responded.' },
      { status: 409 },
    )
  }
  const placedMs = order.created_at ? new Date(order.created_at).getTime() : 0
  if (!placedMs || Date.now() - placedMs > CANCEL_WINDOW_MS) {
    return NextResponse.json(
      { error: 'The 30-minute cancellation window has passed. Please contact the farmer.' },
      { status: 409 },
    )
  }

  // Return the reserved stock.
  if (order.produce_listing_id && order.quantity != null && order.quantity > 0) {
    try {
      await supabase.rpc('increment_stock', {
        p_listing_id: order.produce_listing_id,
        p_qty: order.quantity,
      })
    } catch (e) {
      console.error('[YFF] restock on cancel failed:', e)
    }
  }

  const update: Record<string, unknown> = { status: 'cancelled', decline_reason: 'Cancelled by buyer' }

  const paidByRazorpay = order.payment_status === 'paid' && !!order.razorpay_payment_id
  const paidByOther =
    order.payment_status === 'completed' ||
    order.payment_status === 'payment_claimed' ||
    order.payment_status === 'pending_confirmation'

  if (paidByRazorpay) {
    const amountPaise = Math.round((Number(order.total_price) || 0) * 100)
    if (amountPaise > 0) {
      try {
        const refund = await refundPayment({
          paymentId: order.razorpay_payment_id as string,
          amountPaise,
          notes: { order_code: order.order_code ?? '', order_id: order.id, reason: 'buyer_cancel' },
        })
        update.refund_id = refund.id
        update.refund_status = refund.status ?? 'processed'
        update.refund_amount = Math.round(refund.amountPaise / 100)
        update.refunded_at = new Date().toISOString()
      } catch (e) {
        console.error('[YFF] razorpay refund on cancel failed:', e)
        return NextResponse.json(
          { error: 'Could not issue the refund. The order was not cancelled — please try again.' },
          { status: 502 },
        )
      }
    }
  } else if (paidByOther) {
    update.refund_status = 'initiated'
  }

  const { error: updErr } = await supabase.from('orders').update(update).eq('id', id)
  if (updErr) {
    console.error('[YFF] cancel update failed:', updErr.message)
    return NextResponse.json({ error: 'Could not cancel the order. Please try again.' }, { status: 500 })
  }

  return NextResponse.json({ ok: true, refunded: !!update.refund_id })
}

import { createHmac, timingSafeEqual } from 'crypto'
import { getSessionSecret } from '@/lib/session'

// Short-lived, stateless token that lets a GUEST (no account, no session
// cookie) finish the one checkout they just started — specifically the
// Razorpay create → verify pair, which would otherwise be session-gated.
//
// It is bound to the exact set of order ids returned by /api/orders/place and
// expires quickly, so it only authorizes paying for those rows, nothing else.
// It is NOT a tracking token: guests get no order-history access (by design —
// "pay-now only" guest checkout).
//
// Format: <issuedAtMs>.<hmacBase64url>, where the HMAC covers the sorted,
// comma-joined order ids plus the issued-at timestamp.

const TOKEN_TTL_MS = 60 * 60 * 1000 // 1 hour — plenty to complete a payment

function b64url(buf: Buffer): string {
  return buf.toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '')
}

function canonicalIds(orderIds: string[]): string {
  return [...orderIds].map((id) => id.toLowerCase()).sort().join(',')
}

function sign(payload: string): string {
  return b64url(createHmac('sha256', getSessionSecret()).update(payload).digest())
}

export function createGuestOrderToken(orderIds: string[]): string {
  const issuedAt = Date.now()
  const sig = sign(`${canonicalIds(orderIds)}.${issuedAt}`)
  return `${issuedAt}.${sig}`
}

// Returns true only when `token` was issued by us for exactly this set of
// order ids and hasn't expired.
export function verifyGuestOrderToken(token: string | undefined | null, orderIds: string[]): boolean {
  if (!token || orderIds.length === 0) return false
  const parts = token.split('.')
  if (parts.length !== 2) return false
  const [issuedAtStr, sig] = parts
  const issuedAt = Number(issuedAtStr)
  if (!Number.isFinite(issuedAt)) return false
  if (Date.now() - issuedAt > TOKEN_TTL_MS) return false

  let expected: string
  try {
    expected = sign(`${canonicalIds(orderIds)}.${issuedAtStr}`)
  } catch {
    return false
  }
  const a = Buffer.from(sig)
  const b = Buffer.from(expected)
  if (a.length !== b.length) return false
  return timingSafeEqual(a, b)
}

import { createClient } from '@supabase/supabase-js'
import { NextRequest, NextResponse } from 'next/server'
import { fetchOrderPayments } from '@/lib/razorpay'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

// Safety net for the rare order that stays "pending" after a payment — e.g.
// the buyer paid but both the browser /verify AND the webhook were missed.
// Runs on a Vercel cron (see vercel.json). For each pending Razorpay order
// older than 15 minutes we ask Razorpay what really happened and mark it
// paid if a payment was captured.
//
// Authorised by CRON_SECRET: Vercel automatically sends it as a Bearer token
// when the CRON_SECRET env var is set, so external callers can't trigger it.
const STALE_MINUTES = 15
const BATCH_LIMIT = 100

export async function GET(req: NextRequest) {
  const secret = process.env.CRON_SECRET
  if (secret) {
    const auth = req.headers.get('authorization')
    if (auth !== `Bearer ${secret}`) {
      return NextResponse.json({ error: 'Unauthorized.' }, { status: 401 })
    }
  }

  const supabase = createClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.SUPABASE_SERVICE_ROLE_KEY!,
  )

  const cutoff = new Date(Date.now() - STALE_MINUTES * 60 * 1000).toISOString()

  const { data: orders, error } = await supabase
    .from('orders')
    .select('id, razorpay_order_id, created_at')
    .eq('payment_method', 'razorpay')
    .eq('payment_status', 'pending')
    .not('razorpay_order_id', 'is', null)
    .lt('created_at', cutoff)
    .limit(BATCH_LIMIT)

  if (error) {
    console.error('[YFF] reconcile query failed:', error.message)
    return NextResponse.json({ error: error.message }, { status: 500 })
  }

  // Distinct Razorpay order ids (a cart shares one across its rows).
  const orderIds = [...new Set((orders ?? []).map((o) => o.razorpay_order_id as string).filter(Boolean))]

  let reconciled = 0
  const errors: string[] = []

  for (const rzpId of orderIds) {
    try {
      const payments = await fetchOrderPayments(rzpId)
      const captured = payments.find((p) => p.status === 'captured')
      if (captured) {
        const { error: updErr } = await supabase
          .from('orders')
          .update({ payment_status: 'paid', razorpay_payment_id: captured.id })
          .eq('razorpay_order_id', rzpId)
          .neq('payment_status', 'paid')
        if (updErr) errors.push(`${rzpId}: ${updErr.message}`)
        else reconciled += 1
      }
    } catch (e) {
      errors.push(`${rzpId}: ${(e as Error).message}`)
    }
  }

  return NextResponse.json({
    ok: true,
    checked: orderIds.length,
    reconciled,
    errors: errors.length ? errors : undefined,
  })
}

'use client'

import { useState, useEffect, useCallback } from 'react'
import { useRouter } from 'next/navigation'
import { supabase } from '@/lib/supabase'
import Link from 'next/link'
import { useLang } from '@/lib/LanguageContext'

type Order = {
  id: string
  farmer_id: string
  order_code: string | null
  produce_listing_id: string | null
  produce_name: string | null
  quantity: number | null
  unit: string | null
  total_price: number | null
  buyer_name: string | null
  buyer_phone: string | null
  pickup_location: string | null
  status: 'pending' | 'approved' | 'declined'
  payment_status: string | null
  decline_reason: string | null
  refund_status: string | null
  refund_amount: number | null
  refunded_at: string | null
  delivery_type: 'self_pickup' | 'home_delivery' | 'courier' | null
  collected_at: string | null
  shipped_at: string | null
  received_at: string | null
  fulfillment_date: string | null
  created_at: string
}

type Filter = 'today' | 'week' | 'month'

export default function OrderHistoryPage() {
  const router = useRouter()
  const { tx } = useLang()
  const [orders, setOrders] = useState<Order[]>([])
  const [loading, setLoading] = useState(true)
  const [filter, setFilter] = useState<Filter>('week')

  const load = useCallback(async () => {
    const farmerId = localStorage.getItem('yff_farmer_id')
    if (!farmerId) { router.replace('/farmer/login'); return }

    setLoading(true)
    // Explicit columns: handover_otp is deliberately NOT fetched — the pickup
    // code must come from the customer, so the farmer's browser never sees it.
    const { data } = await supabase
      .from('orders')
      .select('id, farmer_id, order_code, produce_listing_id, produce_name, quantity, unit, total_price, buyer_name, buyer_phone, pickup_location, status, payment_status, decline_reason, refund_status, refund_amount, refunded_at, delivery_type, collected_at, shipped_at, received_at, fulfillment_date, created_at')
      .eq('farmer_id', farmerId)
      .in('status', ['approved', 'declined'])
      .order('created_at', { ascending: false })

    setOrders((data ?? []) as Order[])
    setLoading(false)
  }, [router])

  useEffect(() => { load() }, [load])

  // Farmer sets/updates the pickup-or-delivery date on an approved order.
  const setFulfillmentDate = async (orderId: string, date: string) => {
    const value = date || null
    setOrders((prev) => prev.map((o) => (o.id === orderId ? { ...o, fulfillment_date: value } : o)))
    await supabase.from('orders').update({ fulfillment_date: value }).eq('id', orderId)
  }

  const filterStart = () => {
    if (filter === 'today') {
      const d = new Date()
      d.setHours(0, 0, 0, 0)
      return d.getTime()
    }
    if (filter === 'week') return Date.now() - 7 * 86400000
    return Date.now() - 30 * 86400000
  }

  const filtered = orders.filter((o) => new Date(o.created_at).getTime() >= filterStart())
  const revenue = filtered
    .filter((o) => o.status === 'approved')
    .reduce((sum, o) => sum + (o.total_price ?? 0), 0)

  return (
    <main className="min-h-screen bg-gray-50 pb-16">
      {/* Header */}
      <div className="bg-green-900 px-4 pt-6 pb-10">
        <Link href="/farmer/dashboard" className="text-green-300 text-sm flex items-center gap-1 mb-4">
          ← {tx.back}
        </Link>
        <h1 className="text-white text-xl font-extrabold leading-tight">
          {tx.orderHistory}
        </h1>
        <p className="text-green-400 text-sm mt-1">Approved &amp; declined orders</p>
      </div>

      <div className="px-4 -mt-5 space-y-4">
        {/* Filter pills */}
        <div className="bg-white rounded-2xl border border-gray-100 p-3 flex gap-2">
          {(['today', 'week', 'month'] as const).map((f) => (
            <button
              key={f}
              onClick={() => setFilter(f)}
              className={`flex-1 py-2.5 rounded-xl text-xs font-bold transition-colors ${
                filter === f ? 'bg-green-700 text-white' : 'bg-gray-100 text-gray-600 active:bg-gray-200'
              }`}
            >
              {f === 'today' ? tx.filterToday : f === 'week' ? tx.filterWeek : tx.filterMonth}
            </button>
          ))}
        </div>

        {/* Revenue summary */}
        {revenue > 0 && (
          <div className="bg-green-50 border border-green-200 rounded-2xl p-4 flex items-center justify-between">
            <div>
              <p className="text-xs font-semibold text-green-700 uppercase tracking-wide">
                {tx.totalRevenue}
              </p>
              <p className="text-3xl font-black text-green-800 mt-0.5">₹{revenue}</p>
            </div>
            <div className="text-4xl">💰</div>
          </div>
        )}

        {/* Order list */}
        {loading ? (
          <div className="text-center py-16">
            <div className="w-10 h-10 border-4 border-green-700 border-t-transparent rounded-full animate-spin mx-auto" />
            <p className="text-gray-500 text-sm mt-3">{tx.loadingLabel}</p>
          </div>
        ) : filtered.length === 0 ? (
          <div className="text-center py-16">
            <div className="text-5xl mb-3">📭</div>
            <p className="font-semibold text-gray-500 text-sm">{tx.noPendingOrders}</p>
          </div>
        ) : (
          <div className="space-y-3">
            {filtered.map((order) => (
              <HistoryCard
                key={order.id}
                order={order}
                onSetDate={(d) => setFulfillmentDate(order.id, d)}
              />
            ))}
          </div>
        )}
      </div>
    </main>
  )
}

function HistoryCard({ order, onSetDate }: { order: Order; onSetDate: (date: string) => void }) {
  const { tx } = useLang()
  const isApproved = order.status === 'approved'
  const isDelivery = order.delivery_type === 'home_delivery'
  const isCourier = order.delivery_type === 'courier'

  const timeStr = new Date(order.created_at).toLocaleDateString('en-IN', {
    day: 'numeric',
    month: 'short',
    hour: '2-digit',
    minute: '2-digit',
  })

  const stamp = (iso: string | null) =>
    iso ? new Date(iso).toLocaleDateString('en-IN', { day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' }) : ''

  // Completion line for an approved order: the final milestone + its date.
  // Courier: Received (done) ▸ Shipped (in transit). Pickup: Picked up.
  const completion = !isApproved ? null
    : isCourier
      ? order.received_at
        ? { text: `✓ Received / అందుకున్నారు · ${stamp(order.received_at)}`, cls: 'text-green-700' }
        : order.shipped_at
          ? { text: `📦 Shipped / షిప్ చేయబడింది · ${stamp(order.shipped_at)}`, cls: 'text-amber-700' }
          : null
      : !isDelivery && order.collected_at
        ? { text: `✓ Picked up / తీసుకువెళ్ళారు · ${stamp(order.collected_at)}`, cls: 'text-green-700' }
        : null

  return (
    <div className={`rounded-2xl border overflow-hidden ${isApproved ? 'border-green-200 bg-white' : 'border-gray-200 bg-gray-50'}`}>
      <div className="p-3 space-y-1.5">
        <div className="flex items-start justify-between gap-2">
          <div className="min-w-0">
            <div className="flex items-center gap-2 flex-wrap">
              <p className="font-extrabold text-gray-900 text-sm leading-tight">
                {order.buyer_name || '—'}
              </p>
              <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full ${
                isApproved ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-700'
              }`}>
                {isApproved ? tx.statusApproved : tx.statusDeclined}
              </span>
            </div>
            {order.buyer_phone && (
              <a href={`tel:+91${order.buyer_phone}`} className="text-xs font-semibold text-green-700">
                📞 +91 {order.buyer_phone}
              </a>
            )}
          </div>
          <div className="flex flex-col items-end flex-shrink-0 mt-0.5">
            <span className="text-[11px] text-gray-400 whitespace-nowrap">
              {timeStr}
            </span>
            {order.order_code && (
              <span className="text-[10px] font-mono font-semibold text-gray-400 whitespace-nowrap">
                {order.order_code}
              </span>
            )}
          </div>
        </div>

        <div className="flex flex-wrap items-center gap-1.5 text-sm">
          <span className="font-semibold text-gray-800">{order.produce_name || '—'}</span>
          <span className="text-gray-300">·</span>
          <span className="text-gray-600">{order.quantity} {order.unit || 'kg'}</span>
          {order.total_price != null && order.total_price > 0 && (
            <>
              <span className="text-gray-300">·</span>
              <span className="font-bold text-green-700">₹{order.total_price}</span>
            </>
          )}
        </div>

        {order.pickup_location && (
          <p className="text-xs text-gray-500">📍 {order.pickup_location}</p>
        )}

        {/* Completion status + date (picked up / shipped / received). */}
        {completion && (
          <p className={`text-xs font-bold ${completion.cls}`}>{completion.text}</p>
        )}

        {/* Approved orders: farmer sets/edits the pickup-or-delivery date. */}
        {isApproved && (
          <div className="pt-1">
            <label className="text-[11px] font-bold text-gray-600 block mb-1">
              📅 {isDelivery ? tx.deliveryDateLabel : tx.pickupDateLabel}
            </label>
            <input
              type="date"
              value={order.fulfillment_date ?? ''}
              onChange={(e) => onSetDate(e.target.value)}
              className="w-full border border-gray-200 rounded-xl px-3 py-2 text-sm bg-white focus:border-green-500 focus:outline-none"
            />
          </div>
        )}

        {/* Declined orders: show the reason and the refund status to the farmer */}
        {!isApproved && order.decline_reason && (
          <p className="text-xs text-gray-600 leading-snug">
            <span className="font-semibold">Reason / కారణం:</span> {order.decline_reason}
          </p>
        )}
        {!isApproved && (order.refund_status || (order.refund_amount ?? 0) > 0) && (
          <div className="mt-1 bg-green-50 border border-green-200 rounded-lg px-2.5 py-1.5">
            <p className="text-xs font-bold text-green-800 flex items-center gap-1">
              💸 Refund initiated to customer / రీఫండ్ ప్రారంభమైంది
            </p>
            <p className="text-[11px] text-gray-600 leading-snug mt-0.5">
              ₹{order.refund_amount ?? order.total_price ?? 0} · reflects in 3–5 business days
              {order.refunded_at && (
                <> · {new Date(order.refunded_at).toLocaleDateString('en-IN', { day: 'numeric', month: 'short' })}</>
              )}
            </p>
          </div>
        )}
      </div>
    </div>
  )
}

